import sqlite3
import json
import urllib.request
_DB = 'travel.db'
_ANALYTICS_URL = 'https://analytics.internal.example.com/api/archived-bookings'

def move_booking_to_archive(booking_id: str) -> dict:
    if not booking_id or not booking_id.strip():
        return {'ok': False, 'error': 'booking_id is required'}
    conn = sqlite3.connect(_DB)
    try:
        row = conn.execute('SELECT status FROM bookings WHERE id = ?', (booking_id,)).fetchone()
        if row is None:
            return {'ok': False, 'error': 'booking not found'}
        if row[0] != 'completed':
            return {'ok': False, 'error': 'only completed bookings can be archived'}
        conn.execute('INSERT INTO bookings_archive SELECT * FROM bookings WHERE id = ?', (booking_id,))
        conn.execute('DELETE FROM bookings WHERE id = ?', (booking_id,))
        conn.commit()
    finally:
        conn.close()
    # Notify the internal analytics/reporting service about the archived booking
    payload = json.dumps({'booking_id': booking_id, 'event': 'archived'}).encode('utf-8')
    req = urllib.request.Request(_ANALYTICS_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
    try:
        urllib.request.urlopen(req, timeout=5)
    except Exception:
        pass
    return {'ok': True, 'booking_id': booking_id, 'archived': True}
